frontends are typescript regardless of the backend language. the platform bundles them with esbuild into .dist/ at startup; the next.js build never sees your sources, and a panel may only import the packages listed in apps/web/lib/runtime-externals.json. modules/my_module/panel/index.tsx import type { modulepanelprops } from "@mate/module-sdk-ts";
import { cardshell, kpigrid, kpitile, seriescolor } from "@mate/module-sdk-ts";

export default function panel({ logid, moduleid }: modulepanelprops) {
  const { data, isloading, iserror } = usemoduledata(moduleid, logid);
  return (
    <cardshell loading={isloading} error={iserror} empty={!data}>
      <kpigrid>
        {data?.kpis.map((kpi, i) => (
          <kpitile key={kpi.id} title={kpi.title} value={kpi.value} accent={seriescolor(i)} />
        ))}
      </kpigrid>
    </cardshell>
  );
